import { readdir, readFile, writeFile } from "node:fs/promises";
import { format } from "prettier";

const records = [];
for (const file of (await readdir("src/docs/content"))
  .filter((f) => f.endsWith(".js"))
  .sort()) {
  records.push((await import(`../src/docs/content/${file}`)).default);
}
const typeFor = (value) =>
  ({
    string: "string",
    boolean: "boolean",
    number: "number",
    array: "ReadonlyArray<unknown>",
    "string or number": "string | number",
  })[value] || "unknown";
let output =
  "// Generated by scripts/generate-types.mjs. Update component API records first.\n";
output += "import type { DefineComponent } from 'vue'\n\n";
for (const record of records) {
  output += `/** ${record.description} */\nexport declare const Vw${record.name}: DefineComponent<{\n`;
  for (const prop of record.props)
    output += `  ${prop.name}${prop.default === "required" ? "" : "?"}: ${typeFor(prop.type)}\n`;
  for (const event of record.events) {
    const type =
      event.payload === "none"
        ? ""
        : `value: ${event.payload === "File[]" ? "File[]" : event.payload === "object" ? "Record<string, unknown>" : typeFor(event.payload)}`;
    const name =
      event.name === "update:modelValue"
        ? "onUpdate:modelValue"
        : `on${event.name[0].toUpperCase()}${event.name.slice(1)}`;
    output += `  '${name}'?: (${type}) => void\n`;
  }
  output += "}>\n\n";
}
output = await format(output, { parser: "typescript" });
if (process.argv.includes("--check")) {
  const actual = await readFile("src/lib/index.d.ts", "utf8");
  if (actual !== output)
    throw new Error("Type declarations are stale. Run npm run types.");
  console.log("Type declarations match the component API catalog.");
} else {
  await writeFile("src/lib/index.d.ts", output);
  console.log(`Generated declarations for ${records.length} components.`);
}
